import { useId } from "react";
import type { CSSProperties } from "react";
import "./FocusProgress.css";

export interface FocusProgressProps {
  label: string;
  elapsedMinutes: number;
  totalMinutes: number;
}

export function FocusProgress({
  label,
  elapsedMinutes,
  totalMinutes,
}: FocusProgressProps) {
  const labelId = useId();

  const total = Number.isFinite(totalMinutes)
    ? Math.max(0, Math.round(totalMinutes))
    : 0;
  const elapsed = Number.isFinite(elapsedMinutes)
    ? Math.min(Math.max(Math.round(elapsedMinutes), 0), total)
    : 0;
  const percent = total === 0 ? 0 : (elapsed / total) * 100;
  const isDone = total > 0 && elapsed >= total;

  const fillStyle: CSSProperties = { inlineSize: `${percent}%` };

  return (
    <div
      className={isDone ? "focus-progress is-done" : "focus-progress"}
      role="progressbar"
      tabIndex={0}
      aria-labelledby={labelId}
      aria-valuemin={0}
      aria-valuemax={total}
      aria-valuenow={elapsed}
      aria-valuetext={`${elapsed} of ${total} minutes`}
    >
      <div className="focus-progress-head">
        <span id={labelId} className="focus-progress-label">
          {label}
        </span>
        <span className="focus-progress-count" aria-hidden="true">
          <span className="focus-progress-elapsed">{elapsed}</span> / {total} min
        </span>
      </div>
      <div className="focus-progress-track">
        <div className="focus-progress-fill" style={fillStyle} />
      </div>
    </div>
  );
}
